// 礼装检索文本：名称、页面标题、别名与效果说明都参与匹配。
function ceSearchText(ce) {
  return `${ce.name} ${ce.title} ${(ce.aliases || []).join(" ")} ${ce.description} ${ce.maxDescription}`;
}

